#include <mutex>
#include <condition_variable>
#include <deque>
#include <optional>

template <class T>
class chan {                         // the portable Go-style channel
    std::mutex m_; std::condition_variable not_empty_, not_full_;
    std::deque<T> q_; size_t cap_; bool closed_ = false;
public:
    explicit chan(size_t cap) : cap_(cap) {}

    void send(T v) {
        std::unique_lock lk(m_);
        not_full_.wait(lk, [&]{ return q_.size() < cap_ || closed_; });  // predicate, not a bare wait
        if (closed_) return;                       // send-after-close: no-op
        q_.push_back(std::move(v));
        lk.unlock(); not_empty_.notify_one();
    }
    std::optional<T> recv() {          // nullopt = closed and drained
        std::unique_lock lk(m_);
        not_empty_.wait(lk, [&]{ return !q_.empty() || closed_; });
        if (q_.empty()) return std::nullopt;
        T v = std::move(q_.front()); q_.pop_front();
        lk.unlock(); not_full_.notify_one();
        return v;
    }
    void close() {                     // the SENDER closes
        { std::lock_guard lk(m_); closed_ = true; }
        not_empty_.notify_all(); not_full_.notify_all();   // wake EVERY waiter
    }
};
// SPSC with no blocking: a ring with two atomic<size_t> indices (acquire/release).
// With std::atomic::wait (C++20), wait on a GENERATION counter, not a bare flag -
// otherwise a change between the load and the wait is missed (lost wakeup).
